// ── ARRAIAL D'AJUDA — Pitinga & Mucugê cliffs, Bahian village charm ──
// mt, w1, w2, w3, w, h, bY, bCol, wc, ol, isN, sc — runtime

// Sky gradient (tropical Bahia sunset)
svg += `<defs><linearGradient id="lg-arraial" x1="0" y1="0" x2="0" y2="1">
  <stop offset="0%" stop-color="${isN ? '#0D2B5B' : sc.sky1}"/>
  <stop offset="100%" stop-color="${isN ? '#071A3B' : sc.sky2}"/>
</linearGradient></defs>`;
svg += `<rect x="0" y="0" width="${w}" height="${h}" fill="url(#lg-arraial)"/>`;

// Ocean (warm Bahian waters)
const oceanY = h * 0.66;
svg += `<rect x="0" y="${oceanY}" width="${w}" height="${h - oceanY}" fill="${isN ? '#0A2845' : '#26C6DA'}"/>`;

// Animated waves (Pitinga beach waves)
for (let i = 0; i < 7; i++) {
  const waveY = oceanY + i * 5 + Math.sin(mt * 2.3 + i * 0.8) * 4;
  const waveHeight = 3 + w1 * 2;
  svg += `<path d="M0 ${waveY} Q ${w * 0.25} ${waveY + waveHeight} ${w * 0.5} ${waveY} T ${w} ${waveY}" fill="none" stroke="${isN ? '#4DD0E1' : '#ffffff'}" stroke-opacity="0.4" stroke-width="1.5"/>`;
}

// Beach (golden Bahian sand)
svg += `<rect x="0" y="${oceanY - 25}" width="${w}" height="25" fill="${sc.ground}"/>`;

// Pitinga cliff (left side)
const cliffLeftX = w * 0.15;
const cliffHeight = 70 + w2 * 15;
svg += `<path d="M ${cliffLeftX - 50} ${oceanY - 25} 
           Q ${cliffLeftX} ${oceanY - 25 - cliffHeight} ${cliffLeftX + 50} ${oceanY - 25} 
           Z" fill="${sc.bld}" stroke="#5D4037" stroke-width="${ol * 0.6}"/>`;

// Mucugê cliff (right side)
const cliffRightX = w * 0.75;
const cliffHeightRight = 55 + w3 * 10;
svg += `<path d="M ${cliffRightX - 40} ${oceanY - 25} 
           Q ${cliffRightX} ${oceanY - 25 - cliffHeightRight} ${cliffRightX + 40} ${oceanY - 25} 
           Z" fill="${sc.bld}" stroke="#5D4037" stroke-width="${ol * 0.6}"/>`;

// Cliff vegetation (tropical plants)
for (let i = 0; i < 5; i++) {
  const vx = cliffLeftX - 20 + i * 20;
  const vy = oceanY - 25 - cliffHeight + 15;
  const plantHeight = 10 + Math.sin(i * 1.3 + mt) * 3;
  svg += `<ellipse cx="${vx}" cy="${vy}" rx="8" ry="${plantHeight}" fill="#2E7D32"/>`;
}

for (let i = 0; i < 4; i++) {
  const vx = cliffRightX - 15 + i * 20;
  const vy = oceanY - 25 - cliffHeightRight + 10;
  const plantHeight = 8 + Math.sin(i * 1.5 + mt * 1.2) * 2;
  svg += `<ellipse cx="${vx}" cy="${vy}" rx="6" ry="${plantHeight}" fill="#388E3C"/>`;
}

// Village buildings (traditional Bahian architecture)
for (let i = 0; i < 8; i++) {
  const bx = i * (w / 8.5) + 30;
  const bh = 25 + Math.sin(i * 1.1) * 8 + w1 * 10;
  const bw = 25 + Math.cos(i * 0.7) * 5;

  // Main building
  svg += `<rect x="${bx}" y="${oceanY - 25 - bh}" width="${bw}" height="${bh}" fill="${sc.bld}" rx="2"/>`;

  // Roof (traditional terracotta)
  svg += `<path d="M ${bx - 2} ${oceanY - 25 - bh} L ${bx + bw/2} ${oceanY - 25 - bh - 8} L ${bx + bw + 2} ${oceanY - 25 - bh} Z" fill="#B71C1C"/>`;

  // Windows
  if (isN) {
    const lp = Math.sin(mt * 2.3 + i * 0.9) * 0.5 + 0.5;
    svg += `<rect x="${bx + 5}" y="${oceanY - 25 - bh + 8}" width="6" height="8" fill="#FFD54F" opacity="${0.4 + lp * 0.6}"/>`;
    svg += `<rect x="${bx + bw - 11}" y="${oceanY - 25 - bh + 8}" width="6" height="8" fill="#FFD54F" opacity="${0.4 + lp * 0.8}"/>`;
  } else {
    svg += `<rect x="${bx + 5}" y="${oceanY - 25 - bh + 8}" width="6" height="8" fill="#FFECB3" opacity="0.8"/>`;
    svg += `<rect x="${bx + bw - 11}" y="${oceanY - 25 - bh + 8}" width="6" height="8" fill="#FFECB3" opacity="0.8"/>`;
  }
}

// Palm trees along the beach
for (let i = 0; i < 5; i++) {
  const palmX = w * 0.1 + i * 90;

  // Trunk
  svg += `<rect x="${palmX}" y="${oceanY - 45}" width="5" height="45" fill="#6D4C41"/>`;

  // Fronds (swaying in the breeze)
  for (let j = 0; j < 6; j++) {
    const angle = j * 1.05 - 1.57 + Math.sin(mt * 0.8 + i * 0.5) * 0.3;
    const frondLength = 25 + Math.sin(i * 0.7 + j * 0.5) * 5;
    const fx = palmX + 2.5 + Math.cos(angle) * frondLength;
    const fy = oceanY - 45 + Math.sin(angle) * frondLength;

    svg += `<line x1="${palmX + 2.5}" y1="${oceanY - 45}" 
                 x2="${fx}" y2="${fy}" 
                 stroke="#1B5E20" stroke-width="4" stroke-linecap="round"/>`;
  }
}

// Fishing boats in the water
for (let i = 0; i < 3; i++) {
  const boatX = (w1 * w * 0.7 + i * 100) % (w * 0.7) + 50;
  const boatY = oceanY - 10 + Math.sin(mt * 1.5 + i) * 3;

  // Boat hull
  svg += `<path d="M ${boatX - 15} ${boatY} 
                 Q ${boatX} ${boatY - 8} ${boatX + 15} ${boatY} 
                 Z" fill="#5D4037"/>`;

  // Mast
  svg += `<rect x="${boatX - 1}" y="${boatY - 8}" width="2" height="20" fill="#795548"/>`;

  // Sail
  svg += `<path d="M ${boatX} ${boatY - 8} 
                 L ${boatX + 12} ${boatY - 18} 
                 L ${boatX} ${boatY - 18} 
                 Z" fill="${sc.acc}" opacity="0.8"/>`;
}

// Sun/Moon (tropical sky)
if (!isN) {
  // Sun with glow
  svg += `<circle cx="${w * 0.85}" cy="${h * 0.22}" r="${50 + w1 * 12}" fill="#FFEB3B" opacity="0.2"/>`;
  svg += `<circle cx="${w * 0.85}" cy="${h * 0.22}" r="30" fill="#FFEB3B" opacity="0.7"/>`;

  // Sun rays
  for (let i = 0; i < 8; i++) {
    const rayAngle = (i / 8) * Math.PI * 2;
    const rayLength = 35 + w2 * 10;
    const rx1 = w * 0.85 + Math.cos(rayAngle) * 30;
    const ry1 = h * 0.22 + Math.sin(rayAngle) * 30;
    const rx2 = w * 0.85 + Math.cos(rayAngle) * rayLength;
    const ry2 = h * 0.22 + Math.sin(rayAngle) * rayLength;

    svg += `<line x1="${rx1}" y1="${ry1}" x2="${rx2}" y2="${ry2}" 
                 stroke="#FFEB3B" stroke-width="2" opacity="0.4"/>`;
  }
} else {
  // Moon with craters
  svg += `<circle cx="${w * 0.85}" cy="${h * 0.22}" r="22" fill="#EDE7F6" opacity="0.9"/>`;
  svg += `<circle cx="${w * 0.85 + 5}" cy="${h * 0.22 - 5}" r="18" fill="${isN ? '#0D2B5B' : sc.sky2}" opacity="0.9"/>`;

  // Moon glow
  svg += `<circle cx="${w * 0.85}" cy="${h * 0.22}" r="35" fill="rgba(237, 231, 246, 0.15)"/>`;

  // Stars
  for (let i = 0; i < 15; i++) {
    const starX = (i * 37) % (w - 50) + 25;
    const starY = (i * 23) % (h * 0.4) + 30;
    const twinkle = Math.sin(mt * 3 + i) * 0.5 + 0.5;

    svg += `<circle cx="${starX}" cy="${starY}" r="${1 + twinkle * 0.5}" fill="#FFFFFF" opacity="${0.5 + twinkle * 0.3}"/>`;
  }
}

// Seagulls (animated)
for (let i = 0; i < 3; i++) {
  const birdX = (w1 * w * 0.9 + i * 70) % (w * 0.9) + 30;
  const birdY = h * 0.35 + Math.sin(mt * 2 + i * 1.3) * 15;
  const wingFlap = Math.sin(mt * 4 + i) * 3;

  // Bird body
  svg += `<ellipse cx="${birdX}" cy="${birdY}" rx="8" ry="4" fill="${isN ? '#BDBDBD' : '#FFFFFF'}"/>`;

  // Wings
  svg += `<path d="M ${birdX - 8} ${birdY} 
                 Q ${birdX - 15} ${birdY - 6 - wingFlap} ${birdX - 8} ${birdY}" 
                 fill="none" stroke="${isN ? '#BDBDBD' : '#FFFFFF'}" stroke-width="2"/>`;
  svg += `<path d="M ${birdX + 8} ${birdY} 
                 Q ${birdX + 15} ${birdY - 6 - wingFlap} ${birdX + 8} ${birdY}" 
                 fill="none" stroke="${isN ? '#BDBDBD' : '#FFFFFF'}" stroke-width="2"/>`;
}
